// Sipariş ve stok bildirimi akışlarının ORTAK doğrulaması; iki akış da bu sub-workflow'u çağırır.
// Kurallar sitenin sunucusundaki server/sanitizePayload.js ve src/data/formRules.js ile aynı.
// Site zaten doğruluyor; burası n8n webhook'una doğrudan (siteyi atlayarak) gelen istekler için ikinci kapı.
// Geçersiz istekte hata fırlatılır: çağıran workflow durur, "Hata yakalayıcı" workflow'u kaydı tutar.
// Hata mesajına kişisel veri (ad, e-posta, telefon) yazılmaz.

// Ürün kataloğu: src/data/products.js ile elle senkron. Yeni ürün eklenince burayı da güncelleyin.
const CATALOG = {
  'hus-kuksa': { category: 'kuksa' },
  'ceviz-yemek-kasigi': { category: 'kasik' },
  'kiraz-olcu-kasigi': { category: 'kasik' },
}
const EVENTS = ['order_created', 'stock_notification_requested']
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/
const PHONE_RE = /^[0-9 \-+()]{7,20}$/
const MAX_QUANTITY = 99
const text = (v) => (typeof v === 'string' ? v.trim() : '')

return $input.all().map((item) => {
  const p = item.json.body ?? item.json
  const product = CATALOG[p.productId]
  if (!product) {
    throw new Error(`Bilinmeyen ürün ID'si: "${String(p.productId ?? '(boş)').slice(0, 60)}"`)
  }

  const name = text(p.name)
  const email = text(p.email)
  const phone = text(p.phone)
  const problems = []
  if (!EVENTS.includes(p.event)) problems.push('bilinmeyen olay')
  if (!name || name.length > 80) problems.push('ad boş ya da çok uzun')
  if (email && (email.length > 254 || !EMAIL_RE.test(email))) problems.push('e-posta biçimi geçersiz')
  if (p.consent !== true) problems.push('açık rıza yok')
  if (p.event === 'stock_notification_requested' && !email) problems.push('e-posta gerekli')
  if (p.event === 'order_created') {
    if (!PHONE_RE.test(phone)) problems.push('telefon geçersiz')
    if (!Number.isInteger(p.quantity) || p.quantity < 1 || p.quantity > MAX_QUANTITY) problems.push('adet 1–99 arası tam sayı olmalı')
  }
  if (problems.length) {
    throw new Error(`Geçersiz istek (${p.productId}): ${problems.join(', ')}`)
  }

  // Temizlenmiş payload + katalogdan kategori: sonraki adımlar kategori eşlemesini tekrar tutmasın.
  return {
    json: {
      event: p.event,
      name,
      productId: p.productId,
      productName: text(p.productName),
      ...(p.event === 'order_created' ? { phone, quantity: p.quantity } : {}),
      email,
      consent: true,
      source: text(p.source),
      category: product.category,
    },
  }
})
